 /*masterMpSoBuyerOrderCreation_comfirmUpdateRow*/

UPDATE KEP_AGENCY_PO AP SET   
  AP.AGENT = #{AGENT1},               
  AP.UNIT_PRICE = #{CHANGE_UNIT_PRICE},          
  AP.LIST_PRICE = #{CHANGE_LIST_PRICE}           
WHERE AP.BUYER = #{BUYER}            
  AND AP.BUYER_ITEM_NO = #{BUYER_ITEM_NO}    
  AND AP.KEP_USER_ID = #{st_kep_user_id}


		 /*masterMpSoBuyerOrderCreation_saveGridtoDB*/

INSERT INTO KEP_AGENCY_PO (KEP_USER_ID, BUYER, BUYER_ITEM_NO, ITEM_QTY, UNIT_PRICE, LIST_PRICE, AGENT, REF_PR_NO, IF_FLAG	)	 		
VALUES( UPPER(#{KEP_USER_ID}) , UPPER(#{BUYER}) , UPPER(#{BUYER_ITEM_NO}) , #{ITEM_QTY},  #{UNIT_PRICE}, #{LIST_PRICE},  UPPER(#{AGENT}) , UPPER(#{REF_PR_NO}), 'C' )

