/*masterMpSoBuyerOrderCreation_buyerOrderQuery*/
SELECT AP.KEP_USER_ID ,AP.BUYER ,(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = (SELECT BUYER FROM ICOMCMPY WHERE COM_CODE=AP.BUYER AND STATUS <> 'D')) AS BUYER_NAME ,AP.AGENT ,(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = (SELECT AGENT FROM ICOMCMPY WHERE COM_CODE=AP.AGENT AND STATUS <> 'D')) AS AGENT_NAME ,AP.BUYER_ITEM_NO ,AP.REF_PR_NO ,AP.UNIT_PRICE ,AP.LIST_PRICE ,AP.ITEM_QTY FROM KEP_AGENCY_PO AP WHERE AP.KEP_USER_ID = #{st_kep_user_id} AND NVL(AP.IF_FLAG,'N') = 'C'
AND AP.BUYER = #{st_buyer_code}
ORDER BY AP.KEP_USER_ID, AP.BUYER, AP.BUYER_ITEM_NO

/*masterMpSoBuyerOrderCreation_getUplodingCheck*/ SELECT BUYER_NAME1, AGENT_NAME1, BUYER_ITEM_NO1, BUYER_ITEM_NO2, CHANGE_UNIT_PRICE, CHANGE_LIST_PRICE, BUYER_NAME2, AGENT_NAME2, BUYER_ITEM_NO2, UNIT_PRICE2, LIST_PRICE2, AGENT_FLAG, UNIT_PRICE_FLAG, LIST_PRICE_FLAG, BUYER1, TOT_FLAG, DECODE(BUYER_ITEM_NO2, '' , '계약서품목없음' , DECODE(BYCA_COMORG_CODE, '' , '회원사카탈로그적용조직코드없음' , DECODE(TOT_FLAG,'REG','정상',AGENT_FLAG||' '||UNIT_PRICE_FLAG||' '||LIST_PRICE_FLAG) ) ) TOT_FLAG_TEXT, AGENT1
,KEP_USER_ID ,BUYER ,(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = (SELECT BUYER FROM ICOMCMPY WHERE COM_CODE=BUYER AND STATUS <> 'D')) AS BUYER_NAME ,AGENT ,(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = (SELECT AGENT FROM ICOMCMPY WHERE COM_CODE=AGENT AND STATUS <> 'D')) AS AGENT_NAME ,BUYER_ITEM_NO ,REF_PR_NO ,UNIT_PRICE ,LIST_PRICE ,ITEM_QTY
,BYCA_COMORG_CODE ,MSDS_ERR
FROM ( SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER1) AS BUYER_NAME1, --0 (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT1) AS AGENT_NAME1, --1 A.BUYER_ITEM_NO1, --2 A.UNIT_PRICE1 AS CHANGE_UNIT_PRICE, --3 A.LIST_PRICE1 AS CHANGE_LIST_PRICE, --4 (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER2) AS BUYER_NAME2, --5 (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT2) AS AGENT_NAME2, --6 A.BUYER_ITEM_NO2, --7 A.UNIT_PRICE2, --8 A.LIST_PRICE2, --9 DECODE(A.AGENT1,A.AGENT2,'','협력사불일치') AS AGENT_FLAG, --10 DECODE(A.UNIT_PRICE1,A.UNIT_PRICE2,'','매출단가불일치') AS UNIT_PRICE_FLAG, --11 DECODE(A.LIST_PRICE1,A.LIST_PRICE2,'','매입단가불일치') AS LIST_PRICE_FLAG, --12 A.BUYER1, --13 DECODE(A.AGENT1,A.AGENT2,'R')||DECODE(A.UNIT_PRICE1,A.UNIT_PRICE2,'E')||DECODE(A.LIST_PRICE1,A.LIST_PRICE2,'G') AS TOT_FLAG, --14 A.AGENT1 --15
,A.KEP_USER_ID ,A.BUYER ,A.BUYER_NAME ,A.AGENT ,A.AGENT_NAME ,A.BUYER_ITEM_NO ,A.REF_PR_NO ,A.UNIT_PRICE ,A.LIST_PRICE ,A.ITEM_QTY
,A.BYCA_COMORG_CODE ,(SELECT DECODE(COUNT(*), 0, 'N', 'Y') FROM ICOMCOD1 WHERE TYPE = 'CM11' AND FLAG = 'Y' AND CODE = (SELECT CMS_CATEG_ID FROM ICOMBYIT WHERE BUYER = A.BUYER2 AND BUYER_ITEM_NO = A.BUYER_ITEM_NO2 AND TRIM(MSDS_NO) IS NULL)) AS MSDS_ERR FROM ( SELECT DISTINCT AP.BUYER_ITEM_NO AS BUYER_ITEM_NO1, DECODE(NVL(AP.UNIT_PRICE,0),0,CQ.UNIT_PRICE,AP.UNIT_PRICE) AS UNIT_PRICE1, DECODE(NVL(AP.LIST_PRICE,0),0,CQ.LIST_PRICE,AP.LIST_PRICE) AS LIST_PRICE1, CQ.BUYER_ITEM_NO AS BUYER_ITEM_NO2, CQ.UNIT_PRICE AS UNIT_PRICE2, CQ.LIST_PRICE AS LIST_PRICE2, AP.BUYER AS BUYER1, DECODE(NVL(AP.AGENT,'0'),'0',CQ.AGENT,AP.AGENT) AS AGENT1, CQ.BUYER AS BUYER2, CQ.AGENT AS AGENT2
,AP.KEP_USER_ID ,AP.BUYER ,'' BUYER_NAME ,AP.AGENT ,'' AGENT_NAME ,AP.BUYER_ITEM_NO ,AP.REF_PR_NO ,AP.UNIT_PRICE ,AP.LIST_PRICE ,AP.ITEM_QTY
,(SELECT PY.BYCA_COMORG_CODE FROM ICOMCMPY PY WHERE PY.COM_CODE=AP.BUYER AND PY.STATUS <> 'D' AND PY.BYCA_COMORG_CODE = CQ.BUYER ) BYCA_COMORG_CODE -- 회원사 정보
FROM KEP_AGENCY_PO AP, ICOMCQDT CQ WHERE 1=1 -- CQ.BUYER IN (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=AP.BUYER AND STATUS <> 'D') AND AP.BUYER_ITEM_NO = CQ.BUYER_ITEM_NO(+) AND CQ.STATUS(+) <> 'D' AND AP.KEP_USER_ID = #{st_kep_user_id}
AND AP.BUYER = #{st_buyer_code} AND CQ.BELOW_COMORG_CODE(+) = #{st_buyer_code}
) A ORDER BY A.BUYER1, A.BUYER_ITEM_NO1 )

